// Conserved scalar-flux kernel.
export const JET_KERNEL_META={"radialCount": 512, "diffusionCount": 129, "maxRadius": 3.5, "maxDiffusionRatio": 0.5, "model": "Uniform disk convolved with a 2D Gaussian; conserved scalar flux, not interacting gas dynamics", "layout": "RGBA float32 LE, radius along width, diffusion ratio along height"};
const DATA="";
export function createJetKernel(){const s=atob(DATA),b=new Uint8Array(s.length);for(let i=0;i<s.length;i++)b[i]=s.charCodeAt(i);return {meta:JET_KERNEL_META,pixels:new Float32Array(b.buffer)};}
